// Filter articles from the last week
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

const recentArticles = $input.all().filter(item => {
  const timestamp = new Date(item.json.timestamp);
  return timestamp > oneWeekAgo;
});

// Sort by timestamp (newest first)
recentArticles.sort((a, b) => {
  return new Date(b.json.timestamp) - new Date(a.json.timestamp);
});

// Limit to top 10 articles
return recentArticles.slice(0, 10);

// Format articles for newsletter
const articles = $input.all();
const articleList = articles.map(article => {
  return `• ${article.json.title}\n  ${article.json.summary}\n  Source: ${article.json.link}`;
}).join('\n\n');

return {
  json: {
    articles: articleList,
    count: articles.length,
    dateRange: 'Last 7 days'
  }
};

// Parse OpenAI response and create email
const response = $json.text;
const subject = 'AI News Weekly Digest - ' + new Date().toLocaleDateString();

// Extract subject line if provided
const subjectMatch = response.match(/Subject: (.+)/i);
if (subjectMatch) {
  subject = subjectMatch[1];
}

// Clean up HTML content
let htmlContent = response;
if (!htmlContent.includes('<html>')) {
  htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>AI News Weekly Digest</title>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .header { background: #0077b5; color: white; padding: 20px; text-align: center; }
    .content { padding: 20px; }
    .article { margin-bottom: 20px; padding: 15px; border-left: 4px solid #0077b5; }
    .footer { background: #f5f5f5; padding: 20px; text-align: center; font-size: 12px; }
    a { color: #0077b5; text-decoration: none; }
    a:hover { text-decoration: underline; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🧠 AI News Weekly Digest</h1>
    <p>Your curated summary of the week's top AI and tech news</p>
  </div>
  <div class="content">
    ${htmlContent}
  </div>
  <div class="footer">
    <p>Generated by AI News Summarizer | Powered by n8n</p>
    <p>Unsubscribe: [Your unsubscribe link]</p>
  </div>
</body>
</html>`;
}

return {
  json: {
    subject: subject,
    htmlContent: htmlContent,
    textContent: htmlContent.replace(/<[^>]*>/g, ''),
    recipientCount: $('Filter Recent').item.json.count || 0
  }
};

// Log newsletter sent
const logEntry = {
  timestamp: new Date().toISOString(),
  action: 'newsletter_sent',
  subject: $json.subject,
  recipientCount: $('Format Email').item.json.recipientCount,
  articlesIncluded: $('Filter Recent').item.json.count
};

console.log('📧 Newsletter sent:', logEntry);

return {
  json: logEntry
};
